import re
lines=open('/app/prompt_ocr6.txt').read().splitlines()
ents=[]
for i,l in enumerate(lines,1):
    m=re.match(r'(\d+)\s+(.*)', l)
    if not m: continue
    fr=int(m.group(1)); txt=m.group(2).strip()
    ents.append((fr,txt))

def clean(t):
    t=t.replace('_','').strip()
    if t.startswith('>'): t=t[1:].strip()
    # remove trailing cursor artifacts
    t=t.rstrip('[]|').strip()
    return t.strip()

def has_letter(t):
    return bool(re.search(r'[A-Za-z]', t))

groups=[]
cur=[]
lastfr=None
for fr,txt in ents:
    c=clean(txt)
    if txt.startswith('>') and has_letter(c):
        if cur and lastfr is not None and fr-lastfr>6:
            groups.append(cur); cur=[]
        cur.append((fr,txt,c))
        lastfr=fr
    else:
        if cur:
            groups.append(cur); cur=[]
        lastfr=fr
if cur: groups.append(cur)

print('groups',len(groups))
for idx,g in enumerate(groups,1):
    frs=[x[0] for x in g]
    longest=max(g,key=lambda x:len(x[2]))
    print(f'{idx:03d} [{frs[0]:04d}-{frs[-1]:04d}] candidate={longest[2]!r}')
